-- Seed retiros Grupo Ricci — nome = código do pasto

ALTER TABLE subdivisoes ADD COLUMN IF NOT EXISTS codigo TEXT;
ALTER TABLE subdivisoes ADD COLUMN IF NOT EXISTS codigo_normalizado TEXT;

-- Limpar registros genéricos antigos sem código
DELETE FROM subdivisoes WHERE codigo IS NULL AND nome IN ('Pasto 01','Pasto 02','Confinamento','Piquete 1','Piquete 2');


SELECT f.nome as fazenda, COUNT(s.id) as total FROM subdivisoes s
JOIN fazendas f ON f.id = s.fazenda_id WHERE s.ativo = true
GROUP BY f.nome ORDER BY f.nome;